            if not is_int(val):
                return out(f"cppcheck: error: argument to '{opt}' is not valid - not an integer.\n")
            i += 1
            continue

        if arg.startswith("-x") and len(arg) > 2:
            val = arg[2:]
            if val not in LANG_VALUES:
                return out(f"cppcheck: error: unknown language '{val}' enforced.\n")
            i += 1
            continue

        # -rp=<paths> is a documented short-ish form.
        if arg.startswith("-rp="):
            i += 1
            continue

        # Long flags.
        if arg in BARE_LONG_FLAGS:
            i += 1
            continue

        # --template='{...}' etc use equals.  Without equals most documented
        # value options are reported as unrecognized, not as missing arguments.
        if arg.startswith("--") and "=" in arg:
            name, value = arg.split("=", 1)
            if name in VALUE_LONG:
                res = validate_value_option(name, value, state)
                if res is not None:
                    return res
                i += 1
                continue
            return unrecognized(arg)

        # Long options without '=' that have no bare-flag form are unrecognized.
        if arg.startswith("--"):
            return unrecognized(arg)

        # Anything else beginning with '-' is unknown.
        return unrecognized(arg)

    if state["inputs"] <= 0:
        return out(NO_SOURCE)
    return out(STD_CFG_ERROR)


def main() -> None:
    try:
        rc = parse(sys.argv[1:])
    except BrokenPipeError:
        rc = 1
    raise SystemExit(rc)


if __name__ == "__main__":
    main()
